TABLES = {
    "antibiotics": (
        "chembl_id", "name", "molecule_type", "max_phase", "first_approval", "withdrawn",
        "smiles", "inchikey", "n_indications",
    ),
    "antibiotic_atc": ("chembl_id", "atc_code", "level4", "level4_description", "who_name"),
    "antibiotic_mechanisms": (
